package android.net; public class Uri { final java.net.URI u; private Uri(String s){u=java.net.URI.create(s);} public static Uri parse(String s){return new Uri(s);} public String getScheme(){return u.getScheme();}public String getAuthority(){return u.getAuthority();}public String getPath(){return u.getPath();}public String toString(){return u.toString();}}